function maxBottlesDrunk(numBottles, numExchange) {
  // Explore every order of single drinks and single exchanges, remembering each state's best.
  const memo = new Map();
  const most = (full, empty, price) => {
    const key = full + ',' + empty + ',' + price;
    if (memo.has(key)) return memo.get(key);
    let result = 0;
    if (full > 0) result = Math.max(result, 1 + most(full - 1, empty + 1, price));
    if (empty >= price) result = Math.max(result, most(full + 1, empty - price, price + 1));
    memo.set(key, result);
    return result;
  };
  return most(numBottles, 0, numExchange);
}

