function generate(rand, size) {
  const pick = top => 1 + Math.floor(rand() * top);
  if (size === 'large') return [100 - Math.floor(rand() * 10), pick(rand() < 0.5 ? 10 : 100)];
  const shape = rand();
  if (shape < 0.15) return [pick(20), 1];
  if (shape < 0.3) return [pick(10), pick(100)];
  return [pick(40), pick(12)];
}
